    /**
     * Estadísticas por proceso
     */
    public static function getProcessStatistics($processId, $dateFrom = null, $dateTo = null)
    {
        $c = new Criteria();
        $c->add(WorkflowInstancePeer::BPMNPROCESS_ID, $processId);

        if ($dateFrom) {
            $c->add(WorkflowInstancePeer::FECHA_CREACION, $dateFrom, Criteria::GREATER_EQUAL);
        }

        if ($dateTo) {
            $c->add(WorkflowInstancePeer::FECHA_CREACION, $dateTo, Criteria::LESS_EQUAL);
        }

        $instances = WorkflowInstancePeer::doSelect($c);

        $stats = [
            'total' => count($instances),
            'running' => 0,
            'completed' => 0,
            'failed' => 0,
            'suspended' => 0,
            'avg_duration' => 0,
            'min_duration' => null,
            'max_duration' => null
        ];

        $durations = [];

        foreach ($instances as $instance) {
            $status = $instance->getWorkflowStatus();
            $stats[$status]++;

            if ($status === 'completed' && $instance->getFechaFin()) {
                $startTime = $instance->getFechaCreacion('U');
                $endTime = $instance->getFechaFin('U');
                $duration = ($endTime - $startTime) / 3600; // en horas

                $durations[] = $duration;

                if ($stats['min_duration'] === null || $duration < $stats['min_duration']) {
                    $stats['min_duration'] = $duration;
                }

                if ($stats['max_duration'] === null || $duration > $stats['max_duration']) {
                    $stats['max_duration'] = $duration;
                }
            }
        }

        if (!empty($durations)) {
            $stats['avg_duration'] = array_sum($durations) / count($durations);
        }

        return $stats;
    }

