    /**
     * Obtiene las variables iniciales definidas en el proceso
     * Busca en el StartEvent y en la primera UserTask del proceso
     */
    public static function getProcessInitialVariables(BpmnProcess $process)
    {
        $variables = [];

        try {
            $bpmnXml = $process->getBpmnXml();
            if (!$bpmnXml) {
                return $variables;
            }

            $dom = new DOMDocument();
            $dom->loadXML($bpmnXml);

            $xpath = new DOMXPath($dom);

            // Registrar todos los namespaces que pueden estar en el documento
            $xpath->registerNamespace('bpmn2', 'http://www.omg.org/spec/BPMN/20100524/MODEL');
            $xpath->registerNamespace('bpmn', 'http://www.omg.org/spec/BPMN/20100524/MODEL');
            $xpath->registerNamespace('custom', 'http://custom/schema/bpmn');

            // 1. Buscar en StartEvent
            $variables = array_merge($variables, self::extractVariablesFromElements($xpath, '//bpmn2:startEvent'));
            $variables = array_merge($variables, self::extractVariablesFromElements($xpath, '//bpmn:startEvent'));
            $variables = array_merge($variables, self::extractVariablesFromElements($xpath, '//*[local-name()="startEvent"]'));

            // 2. Si no hay variables en StartEvent, buscar en la primera UserTask
            if (empty($variables)) {
                $variables = array_merge($variables, self::extractVariablesFromElements($xpath, '//bpmn2:userTask'));
                $variables = array_merge($variables, self::extractVariablesFromElements($xpath, '//bpmn:userTask'));
                $variables = array_merge($variables, self::extractVariablesFromElements($xpath, '//*[local-name()="userTask"]'));
            }

            // Eliminar duplicados por 'name'
            $uniqueVariables = [];
            $seenNames = [];
            foreach ($variables as $var) {
                if (!in_array($var['name'], $seenNames)) {
                    $uniqueVariables[] = $var;
                    $seenNames[] = $var['name'];
                }
            }

            return $uniqueVariables;
        } catch (Exception $e) {
            error_log('Error en getProcessInitialVariables: ' . $e->getMessage());
            return [];
        }
    }

    /**
     * Extrae variables de los elementos encontrados por XPath
     */
    private static function extractVariablesFromElements(DOMXPath $xpath, $query)
    {
        $variables = [];
        $elements = $xpath->query($query);

        foreach ($elements as $element) {
            $taskConfig = self::getTaskConfigFromElement($element);

            if ($taskConfig && isset($taskConfig['formFields']) && is_array($taskConfig['formFields'])) {
                foreach ($taskConfig['formFields'] as $field) {
                    $variables[] = [
                        'name' => $field['id'] ?? '',
                        'label' => $field['label'] ?? $field['id'] ?? '',
                        'type' => self::mapFieldType($field['type'] ?? 'string'),
                        'default_value' => $field['defaultValue'] ?? '',
                        'required' => filter_var($field['required'] ?? false, FILTER_VALIDATE_BOOLEAN)
                    ];
                }
            }
        }

        return $variables;
    }

    /**
     * Obtiene el taskConfig de un elemento BPMN
     * Maneja múltiples formas en que puede estar almacenado
     */
    private static function getTaskConfigFromElement(DOMElement $element)
    {
        $taskConfig = null;

        // Método 1: Atributo con namespace (custom:taskConfig)
        // Usar getAttributeNS con el URI del namespace
        $taskConfigStr = $element->getAttributeNS('http://custom/schema/bpmn', 'taskConfig');

        // Método 2: Atributo sin namespace pero con prefijo en el nombre
        if (empty($taskConfigStr)) {
            $taskConfigStr = $element->getAttribute('custom:taskConfig');
        }

        // Método 3: Buscar en todos los atributos
        if (empty($taskConfigStr)) {
            foreach ($element->attributes as $attr) {
                // Buscar atributo que contenga 'taskConfig' en el nombre
                if (
                    strpos($attr->nodeName, 'taskConfig') !== false ||
                    strpos($attr->localName, 'taskConfig') !== false
                ) {
                    $taskConfigStr = $attr->nodeValue;
                    break;
                }
            }
        }

        // Método 4: Buscar en extensionElements
        if (empty($taskConfigStr)) {
            $taskConfigStr = self::getTaskConfigFromExtensionElements($element);
        }

        // Parsear JSON si encontramos algo
        if (!empty($taskConfigStr)) {
            $taskConfig = json_decode($taskConfigStr, true);

            if (json_last_error() !== JSON_ERROR_NONE) {
                error_log('Error parseando taskConfig JSON: ' . json_last_error_msg());
                error_log('taskConfigStr: ' . substr($taskConfigStr, 0, 200));
                return null;
            }
        }

        return $taskConfig;
    }

    /**
     * Busca taskConfig en extensionElements del elemento
     */
    private static function getTaskConfigFromExtensionElements(DOMElement $element)
    {
        $extensionElements = $element->getElementsByTagName('extensionElements');

        if ($extensionElements->length === 0) {
            // Buscar con namespace
            $extensionElements = $element->getElementsByTagNameNS('*', 'extensionElements');
        }

        foreach ($extensionElements as $extElement) {
            // Buscar formData o properties dentro de extensionElements
            $formDataElements = $extElement->getElementsByTagNameNS('*', 'formData');
            foreach ($formDataElements as $formData) {
                // Si hay formData, construir un taskConfig desde él
                return self::buildTaskConfigFromFormData($formData);
            }

            // Buscar properties con taskConfig
            $properties = $extElement->getElementsByTagNameNS('*', 'property');
            foreach ($properties as $prop) {
                $name = $prop->getAttribute('name');
                if ($name === 'taskConfig') {
                    return $prop->getAttribute('value') ?: $prop->nodeValue;
                }
            }
        }

        return null;
    }

    /**
     * Construye taskConfig desde un elemento formData de Camunda/Activiti
     */
    private static function buildTaskConfigFromFormData(DOMElement $formData)
    {
        $fields = [];
        $formFields = $formData->getElementsByTagNameNS('*', 'formField');

        foreach ($formFields as $field) {
            $fields[] = [
                'id' => $field->getAttribute('id'),
                'label' => $field->getAttribute('label') ?: $field->getAttribute('id'),
                'type' => $field->getAttribute('type') ?: 'string',
                'defaultValue' => $field->getAttribute('defaultValue') ?: '',
                'required' => $field->getAttribute('required') === 'true'
            ];
        }

        if (!empty($fields)) {
            return json_encode(['formFields' => $fields]);
        }

        return null;
    }

    /**
