    /**
     * Lista todas las instancias de workflow
     */
    public static function listWorkflows(sfWebRequest $request)
    {
        $c = new Criteria();

        // Filtros opcionales
        if ($processId = $request->getParameter('process_id')) {
            $c->add(WorkflowInstancePeer::BPMNPROCESS_ID, $processId);
        }

        if ($status = $request->getParameter('status')) {
            if ($status == 'completed') {
                $c->add(WorkflowInstancePeer::WORKFLOWSTATUS_ID, WorkflowInstanceStatusBpmn::completed);
            } elseif ($status == 'failed') {
                $c->add(WorkflowInstancePeer::WORKFLOWSTATUS_ID, WorkflowInstanceStatusBpmn::failed);
            } elseif ($status == 'running') {
                $c->add(WorkflowInstancePeer::WORKFLOWSTATUS_ID, WorkflowInstanceStatusBpmn::running);
            } elseif ($status == 'suspended') {
                $c->add(WorkflowInstancePeer::WORKFLOWSTATUS_ID, WorkflowInstanceStatusBpmn::suspended);
            } else {
                $c->add(WorkflowInstancePeer::WORKFLOWSTATUS_ID, null, Criteria::ISNULL);
            }
        }

        $c->addDescendingOrderByColumn(WorkflowInstancePeer::FECHA_CREACION);
        $c->setLimit($request->getParameter('limit', 50));

        $workflows = WorkflowInstancePeer::doSelect($c);

        $result = [];
        foreach ($workflows as $wf) {
            $user_wf = $wf->getUsuarioId() ? usuarioPeer::retrieveByPk($wf->getUsuarioId()) : null;

            $result[] = [
                'id' => $wf->getPrimaryKey(),
                'process_id' => $wf->getBpmnprocessId(),
                'process_name' => $wf->getBpmnprocess()->getNombre(),
                'status' => $wf->getWorkflowstatusId() ? $wf->getWorkflowStatus()->getDescripcion() : 'No Definido',
                'current_element' => $wf->getCurrentNode(),
                'started_by' => $user_wf != null ? $user_wf->getNombreApellido() : 'No Definido',
                'created_at' => $wf->getFechaCreacion('Y-m-d G:i:s'),
                'updated_at' => $wf->getFechaModificacion('Y-m-d G:i:s')
            ];
        }

        return ['success' => true, 'workflows' => $result];
    }

    /**
     * Suspender workflow
     */
    public static function suspendWorkflow($workflowId, $usuario_id)
    {
        $workflow = WorkflowInstancePeer::retrieveByPK($workflowId);

        if (!$workflow) {
            return [
                'success' => false,
                'error' => 'Workflow no encontrado'
            ];
        }

        if ($workflow->getWorkflowstatusId() !== WorkflowInstanceStatusBpmn::running) {
            return [
                'success' => false,
                'error' => 'Solo se pueden suspender workflows activos'
            ];
        }

        $workflow->setWorkflowstatusId(WorkflowInstanceStatusBpmn::suspended);
        $workflow->setFechaModificacion(date('Y-m-d G:i:s'));
        $workflow->save();

        WorkflowInstancePeer::logWorkflowAction($workflowId, 'suspended', 'Workflow suspendido por usuario', $usuario_id);

        return [
            'success' => true
        ];
    }

    /**
     * Reanudar workflow
     */
    public static function resumeWorkflow($workflowId, $usuario_id)
    {
        $workflow = WorkflowInstancePeer::retrieveByPK($workflowId);

        if (!$workflow) {
            return [
