    /**
     * Terminar/Cancelar workflow
     */
    public static function terminateWorkflow($workflowId, $usuario_id)
    {
        $workflow = WorkflowInstancePeer::retrieveByPK($workflowId);

        if (!$workflow) {
            return [
                'success' => false,
                'error' => 'Workflow no encontrado'
            ];
        }

        if (in_array($workflow->getWorkflowstatusId(), [WorkflowInstanceStatusBpmn::completed, WorkflowInstanceStatusBpmn::terminated])) {
            return [
                'success' => false,
                'error' => 'El workflow ya está finalizado'
            ];
        }

        $workflow->setWorkflowstatusId(WorkflowInstanceStatusBpmn::terminated);
        $workflow->setFechaCompletado(date('Y-m-d G:i:s'));
        $workflow->setFechaModificacion(date('Y-m-d G:i:s'));
        $workflow->save();

        // Cancelar todas las tareas pendientes
        $c = new Criteria();
        $c->add(TaskInstancePeer::WORKFLOWINSTANCE_ID, $workflowId);
        $c->add(TaskInstancePeer::TASKINSTANCESTATUS_ID, TaskInstanceStatusBpmn::pending);

        $pendingTasks = TaskInstancePeer::doSelect($c);
        foreach ($pendingTasks as $task) {
            $task->setTaskInstanceStatusId(TaskInstanceStatusBpmn::cancelled);
            $task->setFechaModificacion(date('Y-m-d G:i:s'));
            $task->save();
        }

        WorkflowInstancePeer::logWorkflowAction($workflowId, 'terminated', 'Workflow terminado por usuario', $usuario_id);

        return [
            'success' => true,
            'cancelled_tasks' => count($pendingTasks)
        ];
    }

