    /**
     * Calcular métricas detalladas de un workflow
     */
    public static function calculateWorkflowMetrics(WorkflowInstance $workflow)
    {
        $metrics = [
            'duration' => null,
            'duration_formatted' => '-',
            'total_tasks' => 0,
            'completed_tasks' => 0,
            'completion_rate' => 0,
            'on_time' => true,
            'expected_duration' => null,
            'time_efficiency' => 100,
            'overdue_tasks' => 0,
            'avg_task_duration' => null
        ];

        // Calcular duración total
        if ($workflow->getFechaInicio() && $workflow->getFechaCompletado()) {
            $inicio = new DateTime($workflow->getFechaInicio());
            $fin = new DateTime($workflow->getFechaCompletado());
            $diff = $inicio->diff($fin);

            // Duración en horas
            $metrics['duration'] = ($diff->days * 24) + $diff->h + ($diff->i / 60);

            // Formato legible
            $parts = [];
            if ($diff->d > 0) $parts[] = $diff->d . 'd';
            if ($diff->h > 0) $parts[] = $diff->h . 'h';
            if ($diff->i > 0) $parts[] = $diff->i . 'm';
            $metrics['duration_formatted'] = implode(' ', $parts) ?: '<1m';
        }

        // Obtener todas las tareas
        $c = new Criteria();
        $c->add(TaskInstancePeer::WORKFLOWINSTANCE_ID, $workflow->getPrimaryKey());
        $allTasks = TaskInstancePeer::doSelect($c);

        $metrics['total_tasks'] = count($allTasks);

        $totalTaskDuration = 0;
        $taskWithDuration = 0;

        foreach ($allTasks as $task) {
            if ($task->getTaskInstanceStatusId() === TaskInstanceStatusBpmn::completed) {
                $metrics['completed_tasks']++;

                // Calcular duración de la tarea
                if ($task->getFechaInicio() && $task->getFechaCompletado()) {
                    $taskStart = new DateTime($task->getFechaInicio());
                    $taskEnd = new DateTime($task->getFechaCompletado());
                    $taskDiff = $taskStart->diff($taskEnd);
                    $taskHours = ($taskDiff->days * 24) + $taskDiff->h + ($taskDiff->i / 60);
                    $totalTaskDuration += $taskHours;
                    $taskWithDuration++;
                }

                // Verificar si se completó a tiempo
                if ($task->getFechaVencimiento() && $task->getFechaCompletado()) {
                    $dueDate = new DateTime($task->getFechaVencimiento());
                    $completedDate = new DateTime($task->getFechaCompletado());

                    if ($completedDate > $dueDate) {
                        $metrics['overdue_tasks']++;
                        $metrics['on_time'] = false;
                    }
                }
            }
        }

        // Tasa de completación
        if ($metrics['total_tasks'] > 0) {
            $metrics['completion_rate'] = round(($metrics['completed_tasks'] / $metrics['total_tasks']) * 100, 1);
        }

        // Duración promedio por tarea
        if ($taskWithDuration > 0) {
            $metrics['avg_task_duration'] = round($totalTaskDuration / $taskWithDuration, 1);
        }

        // Calcular eficiencia de tiempo basada en duración esperada del proceso
        $process = $workflow->getBpmnProcess();
        $process_definition = TaskDefinitionPeer::retrieveByProcess($workflow->getBpmnProcessId());
        $expected_duration_process = 0;
        foreach ($process_definition as $key => $value) {
            $expected_duration_process += $value->getDurationExpected();
        }

        if ($process && $expected_duration_process && $metrics['duration']) {
            $expectedHours = $expected_duration_process;
            $metrics['expected_duration'] = $expectedHours;

            if ($metrics['duration'] <= $expectedHours) {
                $metrics['time_efficiency'] = 100;
            } else {
                $metrics['time_efficiency'] = round(($expectedHours / $metrics['duration']) * 100, 1);
            }
        }

        return $metrics;
    }

    /**
     * Calcular estadísticas generales de workflows completados
     */
    public static function calculateCompletedStats($workflows)
    {
        $stats = [
            'total' => count($workflows),
            'on_time' => 0,
            'delayed' => 0,
            'avg_completion_rate' => 0,
            'avg_duration' => 0,
            'total_duration' => 0
        ];

        $totalCompletionRate = 0;
        $totalDuration = 0;
        $workflowsWithDuration = 0;

        foreach ($workflows as $workflow) {
            if ($workflow->getFechaInicio() && $workflow->getFechaCompletado()) {
                $inicio = new DateTime($workflow->getFechaInicio());
                $fin = new DateTime($workflow->getFechaCompletado());
                $diff = $inicio->diff($fin);
                $hours = ($diff->days * 24) + $diff->h + ($diff->i / 60);

                $totalDuration += $hours;
                $workflowsWithDuration++;
            }

            // Verificar si hubo tareas atrasadas
            $c = new Criteria();
            $c->add(TaskInstancePeer::WORKFLOWINSTANCE_ID, $workflow->getPrimaryKey());
            $c->add(TaskInstancePeer::TASKINSTANCESTATUS_ID, TaskInstanceStatusBpmn::completed);
            $tasks = TaskInstancePeer::doSelect($c);

            $hasDelays = false;
            $completedTasks = 0;
            $totalTasks = count($tasks);

            foreach ($tasks as $task) {
                if ($task->getTaskinstancestatusId() === TaskInstanceStatusBpmn::completed) {
                    $completedTasks++;

                    if ($task->getFechaVencimiento() && $task->getFechaCompletado()) {
                        $dueDate = new DateTime($task->getFechaVencimiento());
                        $completedDate = new DateTime($task->getFechaCompletado());

                        if ($completedDate > $dueDate) {
                            $hasDelays = true;
                        }
                    }
                }
            }

            if ($hasDelays) {
                $stats['delayed']++;
            } else {
                $stats['on_time']++;
            }

            if ($totalTasks > 0) {
                $totalCompletionRate += ($completedTasks / $totalTasks) * 100;
            }
        }

        if ($stats['total'] > 0) {
            $stats['avg_completion_rate'] = round($totalCompletionRate / $stats['total'], 1);
        }

        if ($workflowsWithDuration > 0) {
            $stats['avg_duration'] = round($totalDuration / $workflowsWithDuration, 1);
        }

        return $stats;
    }

    /**
     * Calcular métricas de una tarea individual
     */
    public static function calculateTaskMetrics(TaskInstance $task)
    {
        $metrics = [
            'duration' => null,
            'duration_formatted' => '-',
            'status' => $task->getTaskinstanceStatus()->getDescripcion(),
            'on_time' => null,
            'delay' => null,
            'delay_formatted' => null,
            'completion_date' => null,
            'assignee' => null
        ];

        // Calcular duración
        if ($task->getFechaCreacion() && $task->getFechaCompletado()) {
            $start = new DateTime($task->getFechaCreacion());
            $end = new DateTime($task->getFechaCompletado());
            $diff = $start->diff($end);

            // Duración en horas
            $metrics['duration'] = ($diff->days * 24) + $diff->h + ($diff->i / 60);

            // Formato legible
            $parts = [];
            if ($diff->d > 0) $parts[] = $diff->d . 'd';
            if ($diff->h > 0) $parts[] = $diff->h . 'h';
            if ($diff->i > 0) $parts[] = $diff->i . 'm';
            $metrics['duration_formatted'] = implode(' ', $parts) ?: '<1m';

            $metrics['completion_date'] = $task->getFechaCompletado();
        }

        // Verificar cumplimiento de tiempo
        if ($task->getFechaVencimiento()) {
            $dueDate = new DateTime($task->getFechaVencimiento());

            if ($task->getFechaCompletado()) {
                $completedDate = new DateTime($task->getFechaCompletado());

                if ($completedDate <= $dueDate) {
                    $metrics['on_time'] = true;

                    // Calcular cuánto tiempo antes se completó
                    $diff = $completedDate->diff($dueDate);
                    if ($diff->days > 0 || $diff->h > 0 || $diff->i > 0) {
                        $parts = [];
                        if ($diff->d > 0) $parts[] = $diff->d . 'd';
                        if ($diff->h > 0) $parts[] = $diff->h . 'h';
                        if ($diff->i > 0) $parts[] = $diff->i . 'm';
                        $metrics['delay_formatted'] = implode(' ', $parts) . ' antes';
                    }
                } else {
                    $metrics['on_time'] = false;

                    // Calcular retraso
                    $diff = $dueDate->diff($completedDate);
                    $metrics['delay'] = ($diff->days * 24) + $diff->h + ($diff->i / 60);

                    $parts = [];
                    if ($diff->d > 0) $parts[] = $diff->d . 'd';
                    if ($diff->h > 0) $parts[] = $diff->h . 'h';
                    if ($diff->i > 0) $parts[] = $diff->i . 'm';
                    $metrics['delay_formatted'] = implode(' ', $parts) . ' retraso';
                }
            }
        }

        // Usuario asignado
        if ($task->getUsuarioId()) {
            $metrics['assignee'] = $task->getUsuario()->getNombreApellido();
        }

        return $metrics;
    }

    /**
     * Calcular métricas por fase del proceso
     */
    public static function calculatePhaseMetrics($workflow)
    {
        $phases = [];

        // Obtener tareas agrupadas por algún criterio (puedes usar task_definition_key o un campo personalizado)
        $c = new Criteria();
        $c->add(TaskInstancePeer::WORKFLOWINSTANCE_ID, $workflow->getPrimaryKey());
        $c->add(TaskInstancePeer::TASKINSTANCESTATUS_ID, TaskInstanceStatusBpmn::completed);
        $tasks = TaskInstancePeer::doSelect($c);

        // Agrupar por prefijo del nombre de tarea (ejemplo: "Fase1_", "Fase2_")
        $phaseGroups = [];
        foreach ($tasks as $task) {
            $taskName = $task->getTaskName();
            // Intentar extraer fase del nombre (personaliza según tu nomenclatura)
            preg_match('/^(Fase\s*\d+|[A-Z][a-z]+)\s*[-_:]/i', $taskName, $matches);
            $phase = isset($matches[1]) ? trim($matches[1]) : 'General';

            if (!isset($phaseGroups[$phase])) {
                $phaseGroups[$phase] = [
                    'name' => $phase,
                    'tasks' => [],
                    'total_duration' => 0,
                    'task_count' => 0
                ];
            }

            $phaseGroups[$phase]['tasks'][] = $task;
            $phaseGroups[$phase]['task_count']++;

            // Calcular duración
            if ($task->getFechaCreacion() && $task->getFechaCompletado()) {
                $start = new DateTime($task->getFechaCreacion());
                $end = new DateTime($task->getFechaCompletado());
                $diff = $start->diff($end);
                $hours = ($diff->days * 24) + $diff->h + ($diff->i / 60);
                $phaseGroups[$phase]['total_duration'] += $hours;
            }
        }

        // Calcular promedios
        foreach ($phaseGroups as &$phase) {
            if ($phase['task_count'] > 0) {
                $phase['avg_duration'] = $phase['total_duration'] / $phase['task_count'];
            }
        }

        return $phaseGroups;
    }

    /**
     * Construir timeline de ejecución del workflow
     */
    public static function buildWorkflowTimeline(WorkflowInstance $workflow)
    {
        $timeline = [];

        $user = null;
        if ($workflow->getUsuarioId()) {
            $user = UsuarioPeer::retrieveByPK($workflow->getUsuarioId());
        }
        // Evento de inicio
        if ($workflow->getFechaInicio()) {
            $timeline[] = [
                'date' => $workflow->getFechaInicio(),
                'type' => 'start',
                'description' => 'Workflow iniciado',
                'user' => $user ? $user->getNombreApellido() : 'Sistema'
            ];
        }

        // Eventos de tareas
        $c = new Criteria();
        $c->add(TaskInstancePeer::WORKFLOWINSTANCE_ID, $workflow->getPrimaryKey());
        $c->addAscendingOrderByColumn(TaskInstancePeer::FECHA_COMPLETADO);
        $tasks = TaskInstancePeer::doSelect($c);

        foreach ($tasks as $task) {
            if ($task->getFechaCompletado()) {
                $timeline[] = [
                    'date' => $task->getFechaCompletado(),
                    'type' => 'task_completed',
                    'description' => 'Tarea completada: ' . $task->getTaskName(),
                    'user' => $task->getUsuarioId() ? $task->getUsuario()->getNombreApellido() : 'Sistema',
                    'task' => $task
                ];
            }
        }

        // Evento de finalización
        if ($workflow->getFechaCompletado()) {
            $timeline[] = [
                'date' => $workflow->getFechaCompletado(),
                'type' => 'end',
                'description' => 'Workflow completado',
                'user' => $user ? $user->getNombreApellido() : 'Sistema'
            ];
        }

        // Ordenar por fecha
        usort($timeline, function ($a, $b) {
            return strtotime($a['date']) - strtotime($b['date']);
        });

        return $timeline;
    }
}
